import{_ as o,l as n,o as e,c as s,v as r,p as l,x as t,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"Karger 最小割","description":"","frontmatter":{"title":"Karger 最小割","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/karger-min-cut.md","filePath":"cs/karger-min-cut.md","lastUpdated":1789023840000}'),h={name:"cs/karger-min-cut.md"};function m(_,a,g,u,E,f){const i=n("Mermaid");return e(),s("div",null,[a[1]||(a[1]=r('<h1 id="karger-最小割" tabindex="-1">Karger 最小割 <a class="header-anchor" href="#karger-最小割" aria-label="Permalink to &quot;Karger 最小割&quot;">​</a></h1><div class="epigraph"><p>随机收缩边直到两点，得到的割以 $\\Omega(1/n^2)$ 概率为全局最小；重复 $O(n^2\\log n)$ 次高概率成功。</p><footer>—— 据 Karger, Global Min-cuts in RNC, 1993；Karger and Stein, 1996；CLRS 第 23 章对照整理</footer></div><p>上一课<a href="/cs/geometric-robustness">几何精度</a>收束几何。主干<a href="/cs/max-flow-ff">最大流最小割</a>是 \\(s\\)–\\(t\\) 割。全局最小割：无指定 \\(s,t\\)，无向边连通性。缺口是 Karger 随机收缩。不重写 Dinic。后课 Las Vegas / Monte Carlo 分类。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>无向（多重）图。收缩边：两端合并，环丢掉。直到剩 2 顶点，其间重边为割。最小割边数 \\(c\\)，成功概率 \\(\\ge 1/\\binom{n}{2}\\) 量级：每次收缩不碰最小割边的条件概率。Karger–Stein：递归到 \\(n/\\sqrt 2\\) 再分支，时间更好。</p><p>缺口是随机收缩，不是 \\(n\\) 次最大流（也可 \\(O(n)\\) 次流，更重）。</p><h3 id="不是-–-最小割" tabindex="-1">不是 \\(s\\)–\\(t\\) 最小割 <a class="header-anchor" href="#不是-–-最小割" aria-label="Permalink to &quot;不是 $s$–$t$ 最小割&quot;">​</a></h3><p>全局割可小于某对 \\(s\\)–\\(t\\)。指定 \\(s,t\\) 用流。本课全局。</p><p><span class="marginnote">Karger 1993。Karger–Stein 1996。后课把成功概率收进 Monte Carlo 定义。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>实现用并查集 + 随机边（按重边权或邻接表）。重复独立试验取最小。Karger–Stein 递归写清分支。</p>',11)),(e(),l(p,null,{default:t(()=>[c(i,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20G%5B%22%E5%A4%9A%E9%87%8D%E5%9B%BE%22%5D%20--%3E%20CTR%5B%22%E9%9A%8F%E6%9C%BA%E6%94%B6%E7%BC%A9%22%5D%0A%20%20CTR%20--%3E%20CUT%5B%22%E4%B8%A4%E7%82%B9%E9%97%B4%E9%87%8D%E8%BE%B9%22%5D%0A%20%20CUT%20--%3E%20REP%5B%22%E9%87%8D%E5%A4%8D%E5%8F%96%E6%9C%80%E5%B0%8F%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>加权边：按权随机，或先离散。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>最小割边少，随机边更常落在块内。分析用 \\(\\prod (1-c/(m_i))\\)。与最大流：确定多项式，常数大。Karger 简单、随机。与 Borůvka：都收缩，一个为 MST 最轻、一个为均匀随机。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写近线性确定全局最小割的最新结果全文。有向全局割不同。后课默认：全局最小割可用随机收缩。下一课 Las Vegas 与 Monte Carlo。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>随机收缩以多项式分之一得到最小割。</li><li>重复放大成功概率。</li><li>全局，不是 \\(s\\)–\\(t\\)。</li><li>出处：Karger, 1993；Karger and Stein, 1996。</li></ul>',7))])}const C=o(h,[["render",m]]);export{B as __pageData,C as default};
